use vstd::prelude::*;

verus! {
    // remove_front takes a non‐empty Vec<i32> and returns a new Vec<i32>
    // consisting of all but the first element of the input, in the same order.
    fn remove_front(a: &Vec<i32>) -> (res: Vec<i32>)
        requires
            // input must be non‐empty
            a.len() > 0,
        ensures
            // result length is exactly one less than the input
            res.len() == a.len() - 1,
            // each element of res[i] equals a[i+1]
            forall |j: usize| j < res.len() ==> res.index(j) == a.index(j + 1),
    {
        let mut res: Vec<i32> = Vec::new();
        let n = a.len();
        let mut i: usize = 1;
        // build res by pushing a[1], a[2], ..., a[n-1]
        while i < n
            invariant
                // i ranges between 1 and n
                1 <= i,
                i <= n,
                // we've pushed exactly i−1 elements so far
                res.len() == i - 1,
                // and they satisfy res[j] == a[j+1] for all j < res.len()
                forall |j: usize| j < res.len() ==> res.index(j) == a.index(j + 1),
            decreases n - i,
        {
            let x: i32 = a.index(i);
            res.push(x);
            i = i + 1;
        }
        res
    }
}

